a<-commandArgs(TRUE)[1];d<-read.csv(file.path(a,"model_data.private.csv"));cv<-setdiff(names(d),c("psoriasis_case","g0","g1","g2"));z<-d[!is.na(d$g0),];z$g<-z$g0;z$g[z$sex==1]<-z$g[z$sex==1]/2;z$gs<-z$g*z$sex;X<-model.matrix(reformulate(c(cv,"g","gs")),z);cat("design_condition",kappa(X,exact=TRUE),"full_rank",qr(X)$rank==ncol(X),"\n");.libPaths(c(file.path(a,"Rlib"),.libPaths()));library(logistf);print(logistf.control());print(args(logistf:::logistf.fit))
